def ca(x,rule,wrap=False):
 y=[]
 for i in range(len(x)):
  l=x[(i-1)%len(x)] if wrap or i>0 else 0
  c=x[i]
  r=x[(i+1)%len(x)] if wrap or i<len(x)-1 else 0
  idx=(l<<2)|(c<<1)|r
  y.append((rule>>idx)&1)
 return tuple(y)
