def transform(grid):
    out = [row[:] for row in grid]
    centers = list(range(1, len(grid[0]), 3))
    order = sorted(range(len(centers)), key=lambda j: sum(grid[r][centers[j]] == 0 for r in range(1, len(grid), 2)), reverse=True)
    for r in range(len(grid)):
        values = [grid[r][centers[j]] for j in order]
        for c, value in zip(centers, values):
            out[r][c] = value
    return out

